import pytest
from app.engine.platform_auth import parse_chzzk_cookie_text, convert_text_to_netscape_cookies

COOKIE_EDITOR_SAMPLE = """# Netscape HTTP Cookie File
# http://curl.haxx.se/rfc/cookie_spec.html
# This file was generated by Cookie-Editor
.naver.com\tTRUE\t/\tTRUE\t1792584304\tSRT5\t1792583898
#HttpOnly_.naver.com\tTRUE\t/\tTRUE\t1827144004\tBUC\t5OIHZkDFUzKqDGuga7u_qdHUdh3EOrwaKvCggT0rsR8=
.naver.com\tTRUE\t/\tTRUE\t1792585804\tSRT30\t1792583898
.naver.com\tTRUE\t/\tTRUE\t1795176004\tNID_SES\
.naver.com\tTRUE\t/\tTRUE\t1827144004\tNNB\tIWCKQVUDDHKGU
.naver.com\tTRUE\t/\tTRUE\t1827129665\tNAC\tkpVQBQRhDlyz
#HttpOnly_.naver.com\tTRUE\t/\tTRUE\t1827144004\tNID_AUT\tAO2HSqf7LBSr4O6yyjdx3GfK1O2ezeOrZA00ZHEqyYg6YNPMzyd8XBxTwpvvH2IE
#HttpOnly_.nid.naver.com\tTRUE\t/\tTRUE\t1809863909\tNID_JST\tQd4bH6K6G2fhQ1JU91hMQBG82sidf0OKh2vguoaOPmYnM7utYTUpd2GbIQVkGvP+Q6gtyNFwCANbKzCfRXy952GRNbHiLLyMntDTTZT3+xeMdJKrUeeWYDR6byXxUD4MLeIbpe9n6YEW3Js0HnmDOl0nwsKvKvgzdSm/Hhnfhtg=
#HttpOnly_.nid.naver.com\tTRUE\t/\tTRUE\t1827143909\tNID_PK\thyb0NUZ1G0yDlXu8I5IADf7Z5haqFJyyBUP9lAOC4UE=
"""

def test_parse_chzzk_cookie_text_from_cookie_editor():
    values = parse_chzzk_cookie_text(COOKIE_EDITOR_SAMPLE)
    assert values["NID_AUT"] == "AO2HSqf7LBSr4O6yyjdx3GfK1O2ezeOrZA00ZHEqyYg6YNPMzyd8XBxTwpvvH2IE"
    assert values["NID_SES"].startswith("AAABsAor+jEpRhvMyDMS05npNGD5uHjWiSsTclLF3xrIYbb0HMKC8VkoCcwOMFvIo+")

def test_parse_chzzk_cookie_text_from_cookie_header():
    header = 'Cookie: NID_AUT="AO2HSqf7LBSr4O6yyjdx3GfK1O2ezeOrZA00ZHEqyYg6YNPMzyd8XBxTwpvvH2IE"; NID_SES="AAABsAor+jEpRhvMyDMS05npNGD5uHjWiSsTclLF3xrIYbb0HMKC8VkoCcwOMFvIo+"; other=1'
    values = parse_chzzk_cookie_text(header)
    assert values["NID_AUT"] == "AO2HSqf7LBSr4O6yyjdx3GfK1O2ezeOrZA00ZHEqyYg6YNPMzyd8XBxTwpvvH2IE"
    assert values["NID_SES"] == "AAABsAor+jEpRhvMyDMS05npNGD5uHjWiSsTclLF3xrIYbb0HMKC8VkoCcwOMFvIo+"

def test_convert_text_to_netscape_cookies():
    header = 'foo=bar; baz=qux'
    converted = convert_text_to_netscape_cookies(header, 'twitch')
    assert '.twitch.tv\tTRUE\t/\tTRUE\t' in converted
    assert 'foo\tbar' in converted
    assert 'baz\tqux' in converted
